		: { kind: "record", definition: type.lean, fields: type.fields.map(field => field.name), arguments: fields };
}
if(type.kind === "variant" && !containsGraph(type, "callback"))
{
	const cases = type.cases.map(branch => ({ name: branch.name, fields: branch.fields.map(field => field.name), arguments: branch.fields.map(field => tree(field.type, false)) }));
	return cases.flatMap(branch => branch.arguments).every(child => child === null) ? null : { kind: "variant", definition: type.lean, cases };
}

/**
 * Collect the Lean names of records and variants whose fields carry checked Fin bounds,
 * from every export's refinement trees.
 *
 * @param model - Compiler-checked native model.
 */
const nativeErasedMirrors = model => {
	const names = new Set();
	const walk = tree => {
		if(!tree || typeof tree !== "object") return;
		if(["record", "variant"].includes(tree.kind)) names.add(tree.definition);
		for(const child of tree.kind === "variant" ? tree.cases.flatMap(branch => branch.arguments) : tree.arguments ?? []) walk(child);
	};
	for(const item of model.exports) if(item.refinements) [...item.refinements.parameters, item.refinements.result].forEach(walk);
	return names;
};

/**
 * Define each erased mirror and its check and erase functions, children before parents.
 *
 * @param model - Compiler-checked native model; its types are already Nat-erased.
 * @param mirrors - Lean names of the mirrored definitions.
 */
const renderErasedMirrors = (model, mirrors) => {
	const trees = new Map();
	const walk = tree => {
		if(!tree || typeof tree !== "object") return;
		if(["record", "variant"].includes(tree.kind) && !trees.has(tree.definition)) trees.set(tree.definition, tree);
		for(const child of tree.kind === "variant" ? tree.cases.flatMap(branch => branch.arguments) : tree.arguments ?? []) walk(child);
	};
	for(const item of model.exports) if(item.refinements) [...item.refinements.parameters, item.refinements.result].forEach(walk);
	const lines = [], done = new Set();
	for(const type of model.types)
	{
		if(!["record", "variant"].includes(type.kind) || !mirrors.has(type.lean) || done.has(type.lean)) continue;
		done.add(type.lean);
		const mirror = erasedMirror(type.lean), tree = trees.get(type.lean), source = `_root_.${type.lean}`;
		const convert = (refinement, value, checked) => componentRefinementConversion(refinement, value, checked);
		if(type.kind === "record")
		{
			lines.push(`structure ${mirror} where`, ...type.fields.map(field => `  «${field.name}» : ${absoluteLeanType(field.type, mirrors)}`), "");
			lines.push(`def ${mirror}.check (value : ${mirror}) : _root_.Option ${source} := do`
				, ...type.fields.map((field, i) => `  let a${i} ← ${convert(tree.arguments[i], `value.«${field.name}»`, true)}`)
				, `  pure (_root_.${type.constructor} ${type.fields.map((_, i) => `a${i}`).join(" ")})`, "");
			lines.push(`def ${mirror}.erase (value : ${source}) : ${mirror} :=`
				, `  ${mirror}.mk ${type.fields.map((field, i) => convert(tree.arguments[i], `value.«${field.name}»`, false)).join(" ")}`, "");
			continue;
		}
		lines.push(`inductive ${mirror} where`, ...type.cases.map(branch => `  | «${branch.name}» ${branch.fields.map((field, j) => `(a${j} : ${absoluteLeanType(field.type, mirrors)})`).join(" ")} : ${mirror}`), "");
		const pattern = branch => `.«${branch.name}» ${branch.fields.map((_, j) => `a${j}`).join(" ")}`;
		lines.push(`def ${mirror}.check (value : ${mirror}) : _root_.Option ${source} :=`, "  match value with"
			, ...type.cases.map((branch, i) => `  | ${pattern(branch)} => do ${branch.fields.map((_, j) => `let b${j} ← ${convert(tree.cases[i].arguments[j], `a${j}`, true)}; `).join("")}pure (_root_.${branch.constructor} ${branch.fields.map((_, j) => `b${j}`).join(" ")})`), "");
		lines.push(`def ${mirror}.erase (value : ${source}) : ${mirror} :=`, "  match value with"
			, ...type.cases.map((branch, i) => `  | ${pattern(branch)} => ${mirror}.«${branch.name}» ${branch.fields.map((_, j) => convert(tree.cases[i].arguments[j], `a${j}`, false)).join(" ")}`), "");
	}
	return lines;
};

// Records and variants with checked Fin fields cross as erased mirrors: the same fields with
// every bound erased to Nat. Only check builds the source value, through Option, and only
// erase projects one back; no Fin is ever constructed without its decidable proof.
const mirrors = nativeErasedMirrors(model);
lines.push(...renderErasedMirrors(model, mirrors));

const mirrored = mirrors.has(type.lean);
emit(`lb_t${type.key}_make`, type.fields.map((f, i) => ({ name: `a${i}`, type: f.type })), type, `${mirrored ? `${erasedMirror(type.lean)}.mk` : `_root_.${type.constructor}`} ${type.fields.map((_, i) => `a${i}`).join(" ")}`);
type.fields.forEach((field, i) => emit(`lb_t${type.key}_get${i}`, [{ name: "value", type }], field.type, mirrored ? `value.«${field.name}»` : `_root_.${field.projection} value`));

  // Record and variant fields run on both Python floors too, each into its own pair of reports.
  const records312 = "LEAN_BRIDGE_FIN_RECORD_REPORT=build/native-fin-records/python312.json LEAN_BRIDGE_REVIEWED_FIN_RECORD_REPORT=build/native-fin-records/reviewed-python312.json LEAN_BRIDGE_FIN_RECORD_PROFILES=python LEAN_BRIDGE_REVIEWED_FIN_RECORD_PROFILES=python node --test tests/native-fin-records.test.mjs";
  assert.ok(workflow.includes(`          LEAN_BRIDGE_PYTHON="\${{ steps.collection_python312.outputs.python-path }}" ${records312}
          test -s build/native-fin-records/python312.json
          test -s build/native-fin-records/reviewed-python312.json
`));
  assert.ok(workflow.includes(`consumer_command="$consumer_command && LEAN_BRIDGE_PYTHON='\${{ steps.collection_python312.outputs.python-path }}' ${records312}"`));
  assert.ok(workflow.includes("            build/native-fin-records/python.json
            build/native-fin-records/reviewed-python.json
            build/native-fin-records/python312.json
            build/native-fin-records/reviewed-python312.json
"));

// Plain record and variant fields are structural since VO #1442.
const box = { kind: "record", name: "Box", lean: "Box", constructor: "Box.mk", fields: [{ name: "digit", projection: "Box.digit", type: refined }], abi: heap };
validateNativeType(box);
validateNativeType({ kind: "record", name: "Box", lean: "Box", constructor: "Box.mk", fields: [{ name: "digits", projection: "Box.digits", type: product }], abi: heap });
validateNativeType({ kind: "variant", name: "Shape", lean: "Shape", abi: heap, cases: [{ name: "circle", constructor: "Shape.circle", fields: [{ name: "radius", type: refined }] }, { name: "empty", constructor: "Shape.empty", fields: [] }] });
// An instantiated generic structure's fields and callbacks stay unchecked, so a bound there is refused.
const generic = { kind: "record", name: "NatBox", lean: "NatBox", constructor: "Holder.mk", provenance: { structure: "Holder", arguments: [nat] }, fields: [{ name: "digit", projection: "Holder.digit", type: refined }], abi: heap };

/**
 * Count real dispatch in the installed C package with a test-only interposer: public
 * rejections reach neither Lean symbol, raw adapter rejections reach only the adapter,
 * and valid calls reach the adapter and the source.
 *
 * @param consumer - Consumer root containing the installed C package.
 * @param packages - Installed C packages.
 * @param leanPrefix - Pinned Lean installation providing lean.h for raw adapter values.
 */
const observeDispatch = async (consumer, packages, leanPrefix) => {
	const root = join(consumer, "c"), pkg = packages.find(item => item.role === "component");
	const installed = join(root, `${pkg.name}-${pkg.version}-c`), lib = join(installed, "lib");
	const receipt = JSON.parse(await readFile(join(installed, "lean-bridge-package.json")));
	const compile = { ...copiedCleanEnvironment, PATH: join(root, "tools"), PKG_CONFIG_LIBDIR: join(lib, "pkgconfig"), PKG_CONFIG_PATH: "" };
	const strict = ["-std=c11", "-Wall", "-Wextra", "-Werror"];
	await saveLakeFile(root, "interposer.c", finProductArrayDispatchInterposer());
	await saveLakeFile(root, "probe.c", finProductArrayDispatchProbe());
	await runCopied("/usr/bin/cc", [...strict, "-shared", "-fPIC", "interposer.c", "-o", "libdispatch.so"], root, compile);
	const flags = (await runCopied("/usr/bin/pkg-config", ["--cflags", "--libs", receipt.pkgConfig], root, compile)).stdout.trim().split(/\s+/u);
	await runCopied("/usr/bin/cc", [...strict, "-isystem", join(leanPrefix, "include"), "probe.c", ...flags, "-lleanshared", "-o", "probe"], root, compile);
	// Without the interposer the probe refuses to report, so a missing counter cannot pass.
	await assert.rejects(() => runCopied(join(root, "probe"), [], root, copiedCleanEnvironment), /interposer is not loaded/u);
	const run = await runCopied(join(root, "probe"), [], root, { ...copiedCleanEnvironment, LD_PRELOAD: join(root, "libdispatch.so") });
	assert.equal(run.stderr, "");
	const observed = run.stdout.trim().split("\n").map(line => {
		const [step, status, ...counts] = line.split(" ");
		return [step, Number(status), counts.map(Number)];
	});
	assert.deepEqual(observed, finProductArrayDispatchExpected);
	return { columns: finProductArrayDispatchColumns, observed, interposer: "LD_PRELOAD", positiveControl: "valid public and raw calls increment source and adapter counts" };
};
// The installed C package also reports measured dispatch for rows.
const observe = async ({ profile, consumer, packages, environment }) => profile === "c" ? { dispatch: await observeDispatch(consumer, packages, environment.LEAN_BRIDGE_LEAN_PREFIX) } : {};

// Plain record fields are structural since VO #1442; a generic instantiation's fields are not.
validateNativeType({ kind: "record", name: "Box", lean: "Box", constructor: "Box.mk", fields: [{ name: "digits", projection: "Box.digits", type: { kind: "tuple", arguments: [fin("5"), nat], abi: nat.abi } }], abi: nat.abi });
assert.throws(() => validateNativeType({ kind: "record", name: "NatBox", lean: "NatBox", constructor: "Holder.mk", provenance: { structure: "Holder", arguments: [nat] }, fields: [{ name: "digit", projection: "Holder.digit", type: fin("5") }], abi: nat.abi }), /top-level/);

